# Let me search for each song on Spotify to get their IDs. I'll search by song name and match the artist.
spotify_token = spotify_login["access_token"]
archived_song_ids = []
for song in songs_to_archive:
    query = song["song_name"]
    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    if isinstance(results, list) and len(results) > 0:
        # Find the song that matches both title and artist
        matched = False
        for result in results:
            if result["title"].lower() == song["song_name"].lower():
                # Check if artist matches
                artist_names = [a["name"].lower() for a in result["artists"]]
                if song["artist_name"].lower() in artist_names:
                    archived_song_ids.append(result["song_id"])
                    print(f"Found: {result['title']} by {result['artists'][0]['name']} -> ID: {result['song_id']}")
                    matched = True
                    break
        if not matched:
            print(f"NOT FOUND: {song['song_name']} by {song['artist_name']}")
    else:
        print(f"NO RESULTS: {song['song_name']} by {song['artist_name']}")

print(f"\nTotal matched songs: {len(archived_song_ids)}")

